import{at as e,it as t,n,vt as r}from"./chunks/framework.CawbQXU3.js";var i=JSON.parse(`{"title":"Formatting context","description":"","frontmatter":{},"headers":[],"relativePath":"reference/formatting-context/index.md","filePath":"reference/formatting-context.md","lastUpdated":1793537972000}`),a={name:`reference/formatting-context/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e('<h1 id="formatting-context" tabindex="-1">Formatting context <a class="header-anchor" href="#formatting-context" aria-label="Permalink to “Formatting context”">​</a></h1><p>These fields are available for</p><ul><li>version serializing</li><li>searching and replacing in files</li><li>commit messages</li><li>tag names</li><li>tag annotations</li></ul><h2 id="escaped-characters" tabindex="-1">Escaped characters <a class="header-anchor" href="#escaped-characters" aria-label="Permalink to “Escaped characters”">​</a></h2><dl><dt><code>#</code></dt><dd>The literal hash or <a href="https://www.merriam-webster.com/dictionary/octothorpe" target="_blank" rel="noreferrer">octothorpe</a> character.</dd><dt><code>;</code></dt><dd>The literal semicolon character.</dd></dl><h2 id="date-and-time-fields" tabindex="-1">Date and time fields <a class="header-anchor" href="#date-and-time-fields" aria-label="Permalink to “Date and time fields”">​</a></h2><dl><dt><code>now</code></dt><dd>A Python datetime object representing the current local time, without a time zone reference.</dd><dt><code>utcnow</code></dt><dd>A Python datetime object representing the current local time in the UTC time zone.</dd></dl><p>You can provide <a href="https://docs.python.org/3.11/library/datetime.html#strftime-and-strptime-format-codes" target="_blank" rel="noreferrer">additional formatting guidance</a> for datetime objects using formatting codes. Put the formatting codes after the field and a colon. For example, <code>{now:%Y-%m-%d}</code> would output the current local time as <code>2023-04-20</code>.</p><h2 id="source-code-management-fields" tabindex="-1">Source code management fields <a class="header-anchor" href="#source-code-management-fields" aria-label="Permalink to “Source code management fields”">​</a></h2><p>These fields will only have values if the code is in a Git or Mercurial repository.</p><dl><dt><code>commit_sha</code></dt><dd>The latest commit reference.</dd><dt><code>short_commit_sha</code></dt><dd>The short version of the latest commit reference.</dd><dt><code>distance_to_latest_tag</code></dt><dd>The number of commits since the latest tag.</dd><dt><code>dirty</code></dt><dd>A boolean indicating if the current repository has pending changes.</dd><dt><code>branch_name</code></dt><dd>The current branch name.</dd><dt><code>short_branch_name</code></dt><dd>The current branch name, converted to lowercase, with non-alphanumeric characters removed and truncated to 20 characters. For example, <code>feature/MY-long_branch-name</code> would become <code>featuremylongbranchn</code>.</dd></dl><h2 id="version-fields" tabindex="-1">Version fields <a class="header-anchor" href="#version-fields" aria-label="Permalink to “Version fields”">​</a></h2><dl><dt><code>current_version</code></dt><dd>The current version serialized as a string</dd><dt><code>current_&lt;version component&gt;</code></dt><dd>Each version component defined by the <a href="/bump-my-version/pr-preview/pr-461/reference/configuration/global/#parse">version configuration parsing regular expression</a>. The default configuration would have <code>current_major</code>, <code>current_minor</code>, and <code>current_patch</code> available.</dd><dt><code>new_version</code></dt><dd>The new version serialized as a string</dd><dt><code>new_&lt;version component&gt;</code></dt><dd>Each version component defined by the <a href="/bump-my-version/pr-preview/pr-461/reference/configuration/global/#parse">version configuration parsing regular expression</a>. The default configuration would have <code>new_major</code>, <code>new_minor</code>, and <code>new_patch</code> available.</dd></dl><div class="info custom-block"><p class="custom-block-title">Note</p><p>The following fields are only available when serializing a version.</p></div><pre><code>`&lt;version component&gt;`\n: Each version part defined by the [version configuration parsing regular expression](configuration/global.md#parse). The default configuration would have `major`, `minor`, and `patch` available.\n</code></pre><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h2><p>Every environment variable available at runtime is included with a <code>$</code> prefix. For example if <code>USER</code> was in the environment, <code>{$USER}</code> would render that value.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>If you use environment variables in your version serialization, you might want to ensure they are set by executing <code>export VAR=value</code> before running the <code>bump-my-version</code> command.</p></div>',18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};